// Input body is sent by the local orchestrator script (see orchestrator/run_session.js),
// which reads brain/system_prompt.md, brain/tools_schema.json and
// registry/market_registry.json off disk so this workflow never needs
// filesystem access on the n8n host. Nothing in this body is sensitive —
// see schema/intake_schema.json's planning_safe tag.
const body = items[0].json.body || items[0].json;

if (!body.profiles || !Array.isArray(body.profiles) || body.profiles.length === 0) {
  throw new Error('Request body is missing a non-empty "profiles" array.');
}
if (!body.system_prompt || !body.registry) {
  throw new Error('Request body is missing "system_prompt" or "registry".');
}

const runId = `run_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

const allTools = body.tools || [];
const planTools = allTools.filter((t) => ['submit_route_plan', 'flag_new_field'].includes(t.name));

const userContent = JSON.stringify({
  task: 'plan_routes',
  registry: body.registry,
  profiles: body.profiles,
}, null, 2);

return [{
  json: {
    run_id: runId,
    profiles: body.profiles,
    claude_request: {
      model: body.model || 'claude-sonnet-5',
      max_tokens: 8192,
      system: body.system_prompt,
      tools: planTools,
      tool_choice: { type: 'auto' },
      messages: [
        { role: 'user', content: userContent },
      ],
    },
  },
}];

function extractApiError(resp) {
  // n8n's continueOnFail error shape isn't fully consistent across versions,
  // so try a few plausible spots rather than assuming one. Goal: get enough
  // (an HTTP-ish status and/or Anthropic's own error.type) for the caller to
  // tell 'worth retrying' (rate limit, overloaded, 5xx) apart from 'will never
  // work' (bad API key, malformed request) rather than treating every failure
  // the same.
  let status = resp.statusCode || resp.httpCode
    || (resp.error && (resp.error.httpCode || resp.error.statusCode)) || null;
  let apiErrorType = null;
  let message = null;
  const rawError = resp.error;
  if (typeof rawError === 'string') {
    message = rawError;
  } else if (rawError && typeof rawError === 'object') {
    message = rawError.message || rawError.description || JSON.stringify(rawError);
    if (rawError.error && rawError.error.type) apiErrorType = rawError.error.type;
  }
  if (resp.type === 'error' && resp.error && resp.error.type) {
    apiErrorType = resp.error.type;
    message = resp.error.message || message;
  }
  return { message: message || 'Unknown error', status, apiErrorType };
}

// Pull run_id/profiles from the sibling branch's output via the input item
// that carries it (n8n keeps items aligned by index through this linear chain).
const claudeResponse = items[0].json;
const upstream = $('Build Claude Request (Plan)').first().json;

// continueOnFail (set on the Claude — Plan Routes node) puts an error here
// instead of throwing and killing the workflow. Anthropic API errors can also
// come back as a 200 with {type: 'error', ...} in some failure modes — check
// both, and surface enough (error_status/error_type) for the orchestrator to
// classify retryable vs non-retryable rather than guessing from a string.
if (claudeResponse.error || claudeResponse.type === 'error') {
  const info = extractApiError(claudeResponse);
  return [{ json: { run_id: upstream.run_id, route_plans: [], flags: [], error: `Claude API call failed: ${info.message}`, error_status: info.status, error_type: info.apiErrorType } }];
}

const toolUseBlocks = (claudeResponse.content || []).filter((b) => b.type === 'tool_use');
const routePlans = toolUseBlocks
  .filter((b) => b.name === 'submit_route_plan')
  .map((b) => b.input);
const flags = toolUseBlocks
  .filter((b) => b.name === 'flag_new_field')
  .map((b) => b.input);

if (routePlans.length === 0 && flags.length === 0) {
  // Claude responded but didn't call either expected tool — plausibly just
  // model variance on this attempt, worth one more try. error_type is our
  // own marker, not an Anthropic one; the orchestrator treats it as retryable.
  return [{ json: { run_id: upstream.run_id, route_plans: [], flags: [], error: `Claude did not call submit_route_plan or flag_new_field (stop_reason: ${claudeResponse.stop_reason}).`, error_status: null, error_type: 'no_tool_call' } }];
}

return [{
  json: {
    run_id: upstream.run_id,
    route_plans: routePlans,
    flags,
    raw_stop_reason: claudeResponse.stop_reason,
    usage: claudeResponse.usage || null,
  },
}];

// Body sent by orchestrator/run_session.js after it collected redacted
// results from the local worker (worker/server.js) for every planned route.
// `results` here are already redacted per schema/quote_result_schema.json —
// no sensitive field has ever entered this pipeline.
const body = items[0].json.body || items[0].json;

if (!body.run_id || !body.profile_label || !body.results) {
  throw new Error('Request body is missing "run_id", "profile_label", or "results".');
}

const allTools = body.tools || [];
const compareTools = allTools.filter((t) => ['submit_comparison', 'flag_new_field'].includes(t.name));

const userContent = JSON.stringify({
  task: 'normalize_and_compare',
  run_id: body.run_id,
  profile_label: body.profile_label,
  benchmark_coverage: body.benchmark_coverage,
  results: body.results,
}, null, 2);

return [{
  json: {
    run_id: body.run_id,
    claude_request: {
      model: body.model || 'claude-sonnet-5',
      max_tokens: 8192,
      system: body.system_prompt,
      tools: compareTools,
      tool_choice: { type: 'auto' },
      messages: [
        { role: 'user', content: userContent },
      ],
    },
  },
}];

function extractApiError(resp) {
  // n8n's continueOnFail error shape isn't fully consistent across versions,
  // so try a few plausible spots rather than assuming one. Goal: get enough
  // (an HTTP-ish status and/or Anthropic's own error.type) for the caller to
  // tell 'worth retrying' (rate limit, overloaded, 5xx) apart from 'will never
  // work' (bad API key, malformed request) rather than treating every failure
  // the same.
  let status = resp.statusCode || resp.httpCode
    || (resp.error && (resp.error.httpCode || resp.error.statusCode)) || null;
  let apiErrorType = null;
  let message = null;
  const rawError = resp.error;
  if (typeof rawError === 'string') {
    message = rawError;
  } else if (rawError && typeof rawError === 'object') {
    message = rawError.message || rawError.description || JSON.stringify(rawError);
    if (rawError.error && rawError.error.type) apiErrorType = rawError.error.type;
  }
  if (resp.type === 'error' && resp.error && resp.error.type) {
    apiErrorType = resp.error.type;
    message = resp.error.message || message;
  }
  return { message: message || 'Unknown error', status, apiErrorType };
}

const claudeResponse = items[0].json;
const upstream = $('Build Claude Request (Compare)').first().json;

if (claudeResponse.error || claudeResponse.type === 'error') {
  const info = extractApiError(claudeResponse);
  return [{ json: { run_id: upstream.run_id, comparison: null, flags: [], error: `Claude API call failed: ${info.message}`, error_status: info.status, error_type: info.apiErrorType } }];
}

const toolUseBlocks = (claudeResponse.content || []).filter((b) => b.type === 'tool_use');
const comparison = toolUseBlocks.find((b) => b.name === 'submit_comparison');
const flags = toolUseBlocks.filter((b) => b.name === 'flag_new_field').map((b) => b.input);

if (!comparison && flags.length === 0) {
  return [{ json: { run_id: upstream.run_id, comparison: null, flags: [], error: `Claude did not call submit_comparison or flag_new_field (stop_reason: ${claudeResponse.stop_reason}).`, error_status: null, error_type: 'no_tool_call' } }];
}

return [{
  json: {
    run_id: upstream.run_id,
    comparison: comparison ? comparison.input : null,
    flags,
    raw_stop_reason: claudeResponse.stop_reason,
    usage: claudeResponse.usage || null,
  },
}];
